import hashlib, hmac, os
from kyber_py.ml_kem import ML_KEM_768

# A control matrix: every threat from lesson C10 is paired with a control and a LIVE test that the control works in the lesson's reference module.
kem = ML_KEM_768
k = kem.k
ek, dk = kem.keygen()
key, ct = kem.encaps(ek)

def raises(fn):
    try:
        fn(); return False
    except ValueError:
        return True

def test_input_validation():
    return raises(lambda: kem.encaps(ek[:-1])) and raises(lambda: kem.decaps(dk, ct[:-1]))
def test_modulus_check():
    bad = bytearray(ek); bad[0:2] = (4000 | (bad[1] << 8 & 0xF000)).to_bytes(2, "little")
    return raises(lambda: kem.encaps(bytes(bad)))
def test_implicit_rejection():
    t = bytearray(ct); t[7] ^= 1
    out = kem.decaps(dk, bytes(t))
    return out != key and out == hashlib.shake_256(dk[-32:] + bytes(t)).digest(32)
def test_no_distinguishable_failure():
    results = []
    for i in (0, 100, 500, 1000):
        t = bytearray(ct); t[i] ^= 1
        results.append(len(kem.decaps(dk, bytes(t))))
    return len(set(results)) == 1                                            # same output shape for every kind of invalid ciphertext
def test_constant_time_compare():
    return hmac.compare_digest(key, key) and not hmac.compare_digest(key, bytes(32))
def test_key_integrity():
    # an authenticated wrapper around the stored decapsulation key
    wrap_key = os.urandom(32)
    tag = hmac.new(wrap_key, dk, "sha256").digest()
    damaged = bytearray(dk); damaged[5] ^= 1
    return hmac.compare_digest(hmac.new(wrap_key, dk, "sha256").digest(), tag) and not hmac.compare_digest(hmac.new(wrap_key, bytes(damaged), "sha256").digest(), tag)
def test_zeroization():
    buf = bytearray(dk[:64]); view = memoryview(buf)
    for i in range(len(buf)): buf[i] = 0
    return not any(view)
def test_randomness_from_module():
    return kem.keygen()[0] != kem.keygen()[0] and kem.encaps(ek)[1] != kem.encaps(ek)[1]

matrix = [
    ("malformed or truncated input", "input validation (type checks)", test_input_validation, "C10.8"),
    ("out-of-range key coefficients", "modulus check of FIPS 203 7.2", test_modulus_check, "C10.8"),
    ("chosen-ciphertext oracle", "implicit rejection K = J(z || c)", test_implicit_rejection, "C10.5"),
    ("failure that is visible to the peer", "same output shape for every invalid ciphertext", test_no_distinguishable_failure, "C10.5"),
    ("timing of secret comparisons", "constant-time comparison", test_constant_time_compare, "C10.1"),
    ("corrupted stored key", "integrity tag over the stored key", test_key_integrity, "C10.5"),
    ("secrets left in memory", "wipeable buffers", test_zeroization, "C10.12"),
    ("predictable randomness", "randomness generated inside the module", test_randomness_from_module, "C10.6"),
]
print(f"{'threat':<38} {'control':<48} {'live test':>10} {'lesson'}")
for threat, control, test, lesson in matrix:
    print(f"{threat:<38} {control:<48} {'PASS' if test() else 'FAIL':>10} {lesson}")
print()
print("not covered by tests of this kind (they need other methods): timing and cache behaviour of the compiled code (11.2, 11.10), power and fault behaviour of the hardware (11.5, 11.6),")
print("the quality of the entropy source (11.3), supply-chain integrity of the build (11.12). A control that has no test is an assumption.")

import itertools, sys

# Constant-time building blocks written with masks instead of branches. (Python itself is not constant time; the point is the STRUCTURE of the code
# and how to check it: record the sequence of executed lines for different secrets and require the sequences to be identical.)
MASK32 = 0xFFFFFFFF

def ct_is_zero(x):                                  # returns 1 if x == 0 else 0, without a branch (x is a 32-bit value)
    return ((~x & MASK32) & ((x - 1) & MASK32)) >> 31
def ct_select(bit, a, b):                           # a if bit == 1 else b
    mask = (-bit) & MASK32
    return (a & mask) | (b & ~mask & MASK32)
def ct_swap(bit, a, b):                             # swap a and b if bit == 1
    t = (a ^ b) & ((-bit) & MASK32)
    return a ^ t, b ^ t
def ct_equal_bytes(a, b):
    diff = 0
    for x, y in zip(a, b):
        diff |= x ^ y
    return ct_is_zero(diff)
def cond_sub_q(x, q=3329):                          # reduce x in [0, 2q) into [0, q) without a branch: subtract q, add it back if the result went negative
    t = x - q
    return t + (q & -(t >> 31 & 1)) if t < 0 else t

# functional correctness, exhaustively where the range is small
assert all(ct_is_zero(x) == (x == 0) for x in range(70000))
assert all(ct_select(b, 11, 22) == (11 if b else 22) for b in (0, 1))
assert all(ct_swap(b, 5, 9) == ((9, 5) if b else (5, 9)) for b in (0, 1))
assert all(cond_sub_q(x) == (x - 3329 if x >= 3329 else x) for x in range(2 * 3329))
print("branch-free helpers match their specification: ct_is_zero on 70,000 values, ct_select, ct_swap, conditional subtraction of q on all 6,658 inputs of [0, 2q)")

# a tracer: record what executes while the function runs, so control flow can be compared across secret values.
# level "line" records source lines; level "opcode" records every bytecode instruction (finer: it can see a conditional expression inside one line)
def trace_of(fn, level, *args):
    events = []
    def tracer(frame, event, arg):
        if event == "call":
            frame.f_trace_opcodes = (level == "opcode")
        elif event == "line" and level == "line":
            events.append((frame.f_code.co_name, frame.f_lineno))
        elif event == "opcode" and level == "opcode":
            events.append((frame.f_code.co_name, frame.f_lasti))
        return tracer
    sys.settrace(tracer)
    try:
        fn(*args)                                                         # the first traced call of a function delivers no opcode events: discard it
        events.clear()
        fn(*args)
    finally:
        sys.settrace(None)
    return tuple(events)

secret = b"\x13\x37\xc0\xde"
def leaky_equal(guess):
    for a, b in zip(secret, guess):
        if a != b:
            return 0
    return 1
def ct_equal(guess):
    return ct_equal_bytes(secret, guess)
def leaky_cond_sub(x, q=3329):
    if x >= q:
        x -= q
    return x
def ct_cond_sub(x):
    return cond_sub_q(x)

def verdict(name, fn, inputs, level):
    for _ in range(40):                                                   # warm up: CPython specialises bytecode after a few calls, which would otherwise show up as differences
        for i in inputs:
            fn(i)
    traces = {trace_of(fn, level, i) for i in inputs}
    print(f"{name:<52} {level:>6} traces over {len(inputs):>2} inputs: {len(traces):>2} -> {'constant' if len(traces) == 1 else 'DEPENDS ON THE INPUT'}")
def ct_cond_sub_masked(x, q=3329):
    t = x - q
    return t + (q & -((t >> 63) & 1))              # arithmetic shift of the sign: all-ones if t is negative
assert all(ct_cond_sub_masked(x) == (x - 3329 if x >= 3329 else x) for x in range(2 * 3329))
guesses = [secret, bytes([0x00, 0x37, 0xC0, 0xDE]), bytes([0x13, 0x00, 0xC0, 0xDE]), bytes([0x13, 0x37, 0x00, 0xDE]), bytes([0x13, 0x37, 0xC0, 0x00]), bytes(4)]
sample = [0, 1, 1000, 3328, 3329, 5000, 6657]
for level in ("line", "opcode"):
    verdict("comparison with early exit", leaky_equal, guesses, level)
    verdict("comparison with accumulated difference", ct_equal, guesses, level)
    verdict("conditional subtraction with an if statement", leaky_cond_sub, sample, level)
    verdict("'branch-free' version containing a ternary expression", ct_cond_sub, sample, level)
    verdict("conditional subtraction, mask only", ct_cond_sub_masked, sample, level)
    print()
print("the line-level tracer misses the ternary expression because the whole expression sits on one source line; the opcode-level tracer sees it")
print("the mask-only version is correct for all 6,658 inputs and has one trace at both levels: it is the form used in constant-time reference code")
print("limits: this checks control flow of the Python bytecode, not instruction timing or memory access patterns of compiled code; compiled code needs binary-level tools (dudect-style statistical timing tests, secret-tainting under valgrind)")

